import os, random, subprocess, sys, glob, time
runner='/workspace/hts_runner'
seeds=[]
for ext in ('*.cram','*.bam','*.bcf','*.vcf','*.sam'):
  for p in glob.glob('/workspace/repo-vul/src-vul/htslib/test/**/'+ext,recursive=True):
    d=open(p,'rb').read()
    if 20<=len(d)<30000: seeds.append((p,d))
print('nseeds',len(seeds), flush=True)
start=time.time(); count=0
edges=[0,1,2,3,4,5,7,8,9,10,15,16,17,31,32,33,63,64,65,0x7f,0x80,0xff]
while time.time()-start<180:
    p,d=random.choice(seeds); b=bytearray(d)
    nm=random.randint(1,25)
    for _ in range(nm):
        if len(b)==0: break
        op=random.randrange(10); i=random.randrange(len(b))
        if op<3: b[i]=random.randrange(256)
        elif op<5: b[i]=random.choice(edges)
        elif op==5: b[i]^=1<<random.randrange(8)
        elif op==6 and len(b)<50000: b[i:i]=os.urandom(random.randint(1,32))
        elif op==7 and len(b)>1: del b[i:min(len(b),i+random.randint(1,32))]
        elif op==8:
            val=random.choice([0,1,2,3,4,7,8,15,16,31,32,63,64,127,128,255,256,512,1024,65535,65536,0x7fffffff,0xffffffff])
            bs=random.choice([val.to_bytes(4,'little'), val.to_bytes(4,'big')])
            b[i:min(len(b),i+4)]=bs[:min(4,len(b)-i)]
        else:
            j=random.randrange(len(b)); b[i:j]=b[j:i] if i>j else b[i:j]
    path='/dev/shm/tmp_mut'
    open(path,'wb').write(b)
    try:
      r=subprocess.run([runner,path], stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, env={**os.environ,'ASAN_OPTIONS':'abort_on_error=1:detect_leaks=0:allocator_may_return_null=1'}, timeout=0.4)
    except subprocess.TimeoutExpired:
      continue
    count+=1
    if r.returncode!=0:
      err=r.stderr.decode('latin1','replace')
      if 'AddressSanitizer' in err or 'runtime error' in err or r.returncode<0:
        print('FOUND',count,'seed',p,'ret',r.returncode,'len',len(b), flush=True)
        open('/workspace/found_mut','wb').write(b)
        print(err[:10000])
        sys.exit(0)
print('none count',count)
